+/**
+ * Parse Message-Ids from a space-separated list (or single Message-Id).
+ * As per section 3.6.4 of RFC 5322.
+ * i.e. Parse "Message-Id", "In-Reply-To:" and "References:" headers.
+ *
+ * Examples:
+ * "" => {}
+ * "<test@example.com>" => {"test@example.com"}
+ * "<foo23@example.com> <bar99@blah.org>"
+ *   => ["foo23@example.com", bar99@blah.org"}
+ * "\t\t\t   <foo23@example.com>    <bar99@blah.org> \t\t "
+ *    => {"foo23@example.com", bar99@blah.org"}
+ * "foo bar" => {"foo","bar"}
+ *
+ * Some currently-undefined corner-cases...
+ * "<<<foo bar" => {"<<foo","bar"}?
+ * "<foo bar>" => ???
+ * etc...
+ */
 nsTArray<nsCString> ParseIdentificationFields(nsACString const& m);

 /**
@@ -513,4 +515,18 @@ nsresult LocalizeMessage(mozilla::intl::Localization* l10n,
                          nsTArray<std::pair<nsCString, nsCString>> const& args,
                          nsACString& message);

+/**
+ * StringFields() splits a string into fields separated by runs of consecutive
+ * ASCII white space characters. It returns a list of substrings, none of
+ * which will be empty.
+ * Leading and trailing whitespace will be discarded. If the string is empty
+ * or contains only whitespace, an empty array will be returned.
+ *
+ * Examples:
+ * "" => {}
+ * " foo bar " => {"foo", "bar"}
+ * "  foo\r\n  bar" => {"foo", "bar"}
+ */
+nsTArray<nsCString> StringFields(nsACString const& s);
+
 #endif  // COMM_MAILNEWS_BASE_SRC_NSMSGUTILS_H_
diff --git a/mailnews/base/test/gtest/TestMsgUtils.cpp b/mailnews/base/test/gtest/TestMsgUtils.cpp
index 0448e934249..eaf5630ce4b 100644
--- a/mailnews/base/test/gtest/TestMsgUtils.cpp
+++ b/mailnews/base/test/gtest/TestMsgUtils.cpp
@@ -91,3 +91,26 @@ TEST(TestMsgUtils, FilenameEncodingIsNotUnique)
   ASSERT_EQ(DecodeFilename(u"foo/bar"_ns), "foo/bar"_ns);
   ASSERT_EQ(DecodeFilename(u"%66%6f%6f%2fbar"_ns), "foo/bar"_ns);
 }
+
+TEST(TestMsgUtils, StringFields)
+{
+  struct {
+    nsLiteralCString input;
+    nsTArray<nsCString> expected;
+  } testCases[] = {
+      {""_ns, {}},
+      {"   "_ns, {}},
+      {"foo"_ns, {"foo"_ns}},
+      {"foo bar"_ns, {"foo"_ns, "bar"_ns}},
+      {"  foo   bar  "_ns, {"foo"_ns, "bar"_ns}},
+      {"foo\r\nbar\r\n"_ns, {"foo"_ns, "bar"_ns}},
+      {"foo\t\fbar"_ns, {"foo"_ns, "bar"_ns}},
+      {"デコポン 한라봉 SumoCitrus"_ns,
+       {"デコポン"_ns, "한라봉"_ns, "SumoCitrus"_ns}},
+  };
+
+  for (auto const& t : testCases) {
+    auto got = StringFields(t.input);
+    ASSERT_EQ(got, t.expected);
+  }
+}
